        self.handle_expiration_processing()

        if self.held_option is not None:
            self.evaluate_exit(data)

        if self.pending_entry_bar_end is not None:
            self.pending_entry_bar_end = None
            self.try_enter(data)

    def try_enter(self, data):
        if self.no_entry_date == self.time.date():
            return

        if self.held_option is not None and self.portfolio[self.held_option].quantity != 0:
            return

        if self.entry_order_id is not None:
            return

        if self.exit_order_id is not None:
            return

        spy_bar = data.bars.get(self.spy)
        if spy_bar is None or spy_bar.close <= 0:
            self.debug("Skipped entry: no current SPY TradeBar.")
            return

        chain = data.option_chains.get(self.option_symbol)
        if chain is None:
            self.debug("Skipped entry: no option chain in current Slice.")
            return

        minimum_expiry = self.time.date() + timedelta(days=7)
        expirations = sorted({
            contract.expiry.date()
            for contract in chain
            if contract.right == OptionRight.CALL
            and contract.expiry.date() >= minimum_expiry
        })

        if not expirations:
            self.debug("Skipped entry: no call expiration at least 7 calendar days away.")
            return

        selected_expiry = expirations[0]
        minimum_strike = spy_bar.close * 1.01

        candidates = [
            contract for contract in chain
            if contract.right == OptionRight.CALL
            and contract.expiry.date() == selected_expiry
            and contract.strike >= minimum_strike
        ]

        if not candidates:
            self.debug(
                f"Skipped entry: no eligible calls for {selected_expiry} "
                f"at or above {minimum_strike:.2f}."
            )
            return

        selected = sorted(
            candidates,
            key=lambda contract: (contract.strike, str(contract.symbol))
        )[0]

        ticket = self.market_order(selected.symbol, 1)
        self.entry_order_id = ticket.order_id
        self.debug(
            f"Entry submitted: {selected.symbol}, expiry {selected_expiry}, "
            f"strike {selected.strike}."
        )

    def evaluate_exit(self, data):
        quantity = self.portfolio[self.held_option].quantity
        if quantity <= 0:
            return

        expiry_date = self.held_option.id.date.date()
