            self.no_entry_date = self.time.date()
            self.submit_exit("expiration processing")
            return

        previous_trading_day = self.securities[self.spy].exchange.hours.get_previous_trading_day(
            self.held_option.id.date
        ).date()

        if (
            self.time.date() == previous_trading_day
            and self.time.hour == 15
            and self.time.minute == 45
        ):
            self.submit_exit("15:45 pre-expiration time stop")
            return

        if self.entry_fill_price is None or self.entry_fill_price <= 0:
            return

        quote = data.quote_bars.get(self.held_option)
        if quote is None or quote.bid is None or quote.ask is None:
            return

        bid = quote.bid.close
        ask = quote.ask.close
        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= self.entry_fill_price * 1.50:
            self.submit_exit(
                f"50% profit target reached at midpoint {midpoint:.2f}"
            )

    def handle_expiration_processing(self):
        if self.held_option is None:
            return

        if self.portfolio[self.held_option].quantity <= 0:
            return

        if self.time.date() >= self.held_option.id.date.date():
            self.no_entry_date = self.time.date()
            self.submit_exit("expiration processing")

    def handle_unexpected_spy_position(self):
        quantity = self.portfolio[self.spy].quantity
        if quantity == 0:
            return

        if not self.has_open_order(self.spy):
            self.debug(
                f"Unexpected SPY position ({quantity}) from exercise/assignment; liquidating."
            )
            self.market_order(self.spy, -quantity)

    def submit_exit(self, reason):
        if self.held_option is None:
            return

        quantity = self.portfolio[self.held_option].quantity
        if quantity <= 0 or self.has_open_order(self.held_option):
            return

        for order in self.transactions.get_open_orders(self.held_option):
            self.transactions.cancel_order(order.id)

        ticket = self.market_order(self.held_option, -quantity)
        self.exit_order_id = ticket.order_id
        self.debug(f"Exit submitted: {self.held_option}; {reason}.")

    def has_open_order(self, symbol):
        return len(self.transactions.get_open_orders(symbol)) > 0

    def on_order_event(self, order_event):
        if order_event.order_id == self.entry_order_id:
            if (
                order_event.status == OrderStatus.FILLED
                and order_event.fill_quantity > 0
            ):
                self.held_option = order_event.symbol
                self.entry_fill_price = order_event.fill_price
                self.entry_order_id = None
                self.debug(
                    f"Entry filled: {self.held_option} at {self.entry_fill_price:.2f}."
                )
            elif order_event.status in (
                OrderStatus.CANCELED,
                OrderStatus.INVALID
            ):
                self.entry_order_id = None
                self.debug(f"Entry order did not fill: {order_event.status}.")

        if order_event.order_id == self.exit_order_id:
            if order_event.status == OrderStatus.FILLED:
                self.debug(
                    f"Exit filled: {order_event.symbol} at {order_event.fill_price:.2f}."
                )
                self.held_option = None
                self.entry_fill_price = None
                self.exit_order_id = None
