        self.entry_order_id = None
        self.exit_order_id = None
        self.held_contract = None
        self.held_expiry = None
        self.entry_fill_price = None
        self.no_entry_dates = set()

        consolidator = TradeBarConsolidator(timedelta(minutes=5))
        consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(self.spy, consolidator)

        self.Schedule.On(
            self.DateRules.EveryDay(self.spy),
            self.TimeRules.At(15, 45),
            self.OnTimeStop
        )

    def OnFiveMinuteBar(self, bar):
        previous_ready = self.fast.IsReady and self.slow.IsReady
        previous_fast = self.fast.Current.Value
        previous_slow = self.slow.Current.Value

        # Only actual consolidated bars update the averages.
        self.fast.Update(bar.EndTime, bar.Close)
        self.slow.Update(bar.EndTime, bar.Close)

        end_time = bar.EndTime.time()
        eligible_time = (
            end_time >= self.TimeRules.At(9, 45).TimeOfDay and
            end_time <= self.TimeRules.At(14, 30).TimeOfDay
        )

        if (previous_ready and self.fast.IsReady and self.slow.IsReady and eligible_time and
                previous_fast <= previous_slow and
                self.fast.Current.Value > self.slow.Current.Value):
            self.pending_signal_time = bar.EndTime

    def OnData(self, data):
        self.HandleUnexpectedSpyPosition()
        self.HandleExpirationProcessing()

        if self.held_contract is not None and self.Portfolio[self.held_contract].Invested:
            self.CheckProfitTarget(data)

        if self.pending_signal_time is None:
            return

        # Signals are valid only in the Slice immediately following that bar close.
        if self.Time != self.pending_signal_time:
            self.pending_signal_time = None
            return

        self.pending_signal_time = None
        self.TryEnter(data)

    def TryEnter(self, data):
        if self.Time.date() in self.no_entry_dates:
            return

        if self.held_contract is not None and self.Portfolio[self.held_contract].Invested:
            return

        if self.entry_order_id is not None:
            return

        spy_bar = data.Bars.get(self.spy)
        if spy_bar is None or spy_bar.Close <= 0:
            self.Debug(f"{self.Time}: skipped entry; no current SPY price")
            return

        chain = data.OptionChains.get(self.option_symbol)
        if chain is None:
            self.Debug(f"{self.Time}: skipped entry; no option chain")
            return

        minimum_expiry = self.Time.date() + timedelta(days=7)
        expiries = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Right == OptionRight.Call and contract.Expiry.date() >= minimum_expiry
        })

        if not expiries:
            self.Debug(f"{self.Time}: skipped entry; no expiration at least 7 calendar days away")
            return

        selected_expiry = expiries[0]
        minimum_strike = spy_bar.Close * 1.01

        candidates = [
            contract for contract in chain
            if (contract.Right == OptionRight.Call and
                contract.Expiry.date() == selected_expiry and
