            self.Debug(f"{self.Time}: skipped entry; no eligible call at selected expiration")
            return

        selected = sorted(candidates, key=lambda c: (c.Strike, str(c.Symbol)))[0]
        ticket = self.MarketOrder(selected.Symbol, 1, tag="Bullish 5-minute MA crossover entry")
        self.entry_order_id = ticket.OrderId
        self.Debug(f"{self.Time}: submitted entry for {selected.Symbol}")

