        if self.entry_fill_price is None or self.exit_order_id is not None:
            return

        midpoint = self.GetCurrentMidpoint(data, self.held_contract)
        if midpoint is None:
            return

        if midpoint >= self.entry_fill_price * 1.50:
            self.SubmitExit("50% profit target")
            self.Debug(f"{self.Time}: profit-target exit submitted for {self.held_contract}")

    def OnTimeStop(self):
        if self.held_contract is None or not self.Portfolio[self.held_contract].Invested:
            return

        previous_trading_day = self.Securities[self.spy].Exchange.Hours.GetPreviousTradingDay(
            self.held_expiry
        ).date()

        if self.Time.date() == previous_trading_day:
            self.SubmitExit("Day-before-expiration 15:45 exit")
            self.Debug(f"{self.Time}: time-stop exit submitted for {self.held_contract}")

    def HandleExpirationProcessing(self):
        if self.held_contract is None:
            return

        if self.Time.date() >= self.held_expiry.date():
            self.no_entry_dates.add(self.Time.date())

            if self.Portfolio[self.held_contract].Invested:
                self.SubmitExit("Expiration safety liquidation")
                self.Debug(f"{self.Time}: expiration safety exit submitted for {self.held_contract}")

    def HandleUnexpectedSpyPosition(self):
        quantity = self.Portfolio[self.spy].Quantity
        if quantity == 0:
            return

        if any(order.Quantity * quantity < 0 for order in self.Transactions.GetOpenOrders(self.spy)):
            return

        self.no_entry_dates.add(self.Time.date())
        self.MarketOrder(self.spy, -quantity, tag="Unexpected exercise/assignment liquidation")
        self.Debug(f"{self.Time}: unexpected SPY exercise/assignment position liquidated")

    def SubmitExit(self, reason):
        if self.held_contract is None or self.exit_order_id is not None:
            return

        quantity = self.Portfolio[self.held_contract].Quantity
        if quantity <= 0:
            return

        # Cancel any pre-existing sell exit orders before creating this market exit.
        for order in self.Transactions.GetOpenOrders(self.held_contract):
            if order.Quantity < 0:
                self.Transactions.GetOrderTicket(order.Id).Cancel("Replacing exit order")

        ticket = self.MarketOrder(self.held_contract, -quantity, tag=reason)
        self.exit_order_id = ticket.OrderId

    def GetCurrentMidpoint(self, data, symbol):
        quote = data.QuoteBars.get(symbol)
        if quote is not None and quote.Bid is not None and quote.Ask is not None:
            bid = quote.Bid.Close
            ask = quote.Ask.Close
            if bid > 0 and ask > 0:
                return (bid + ask) / 2.0

