        if previous_fast is None or previous_slow is None:
            return

        if previous_fast <= previous_slow and self.fast.Current.Value > self.slow.Current.Value:
            bar_time = bar.EndTime.time()
            if time(9, 45) <= bar_time <= time(14, 30):
                self.pending_crossover_bars.append(bar.EndTime)

    def OnData(self, data):
        self.LiquidateUnexpectedSpyPosition()

        if self.held_symbol is not None and self.held_expiry is not None:
            if self.Time.date() >= self.held_expiry.date():
                self.expiration_exit_date = self.Time.date()
                self.CloseHeldOption("expiration processing")
            else:
                self.CheckProfitTarget(data)

        while self.pending_crossover_bars:
            self.pending_crossover_bars.pop(0)
            self.TryEnter(data)

    def TryEnter(self, data):
        if self.expiration_exit_date == self.Time.date():
            return

        if self.held_symbol is not None or self.Portfolio.Invested:
            return

        if self.pending_entry_symbol is not None:
            return

        if self.exit_ticket is not None and self.exit_ticket.Status not in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        ):
            return

        chain = data.OptionChains.get(self.option_symbol)
        if chain is None:
            self.Debug("Skipped entry: no option chain in current Slice")
            return

        minimum_expiry = self.Time.date() + timedelta(days=7)
        eligible_expiries = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Expiry.date() >= minimum_expiry
        })

        if not eligible_expiries:
            self.Debug("Skipped entry: no expiration at least 7 calendar days away")
            return

