        if order_event.Symbol == self.pending_entry_symbol:
            if order_event.Status == OrderStatus.Filled:
                self.held_symbol = order_event.Symbol
                self.entry_fill_price = float(order_event.FillPrice)
                self.pending_entry_symbol = None
                self.entry_order_id = None
                self.Debug(
                    f"Entry filled: {self.held_symbol}, "
                    f"price={self.entry_fill_price:.2f}"
                )
            elif order_event.Status in (OrderStatus.Canceled, OrderStatus.Invalid):
                self.Debug(f"Entry canceled/invalid: {order_event.Symbol}")
                self.pending_entry_symbol = None
                self.entry_order_id = None
                self.held_expiry = None

        if self.held_symbol is not None and order_event.Symbol == self.held_symbol:
            if order_event.Status == OrderStatus.Filled and self.Portfolio[self.held_symbol].Quantity == 0:
                self.Debug(f"Exit filled: {self.held_symbol}")
                self.held_symbol = None
                self.held_expiry = None
                self.entry_fill_price = None
                self.exit_ticket = None

        self.LiquidateUnexpectedSpyPosition()
