from AlgorithmImports import *
from datetime import datetime, timedelta


class FiveMinuteSpyCallCrossoverAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone(TimeZones.NewYork)

        equity = self.AddEquity("SPY", Resolution.Minute)
        equity.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy = equity.Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        self.option_symbol = option.Symbol
        option.SetFilter(-200, 200, timedelta(days=0), timedelta(days=180))

        self.closes = RollingWindow[float](21)
        self.pending_entry_bar_end = None

        self.held_option = None
        self.entry_price = None
        self.entry_ticket = None
        self.exit_ticket = None
        self.spy_flatten_ticket = None
        self.no_entry_date = None

        # Calendar-based consolidation keeps five-minute bars aligned to NY clock
        # boundaries: 09:30-09:35, 09:35-09:40, and so on.
        consolidator = TradeBarConsolidator(self.FiveMinuteCalendar)
        consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(self.spy, consolidator)

    def FiveMinuteCalendar(self, time):
        start = time.Date.AddHours(time.Hour).AddMinutes(time.Minute - time.Minute % 5)
        return CalendarInfo(start, timedelta(minutes=5))

    def OnFiveMinuteBar(self, sender, bar):
        self.closes.Add(float(bar.Close))

        # A current 20-bar SMA and its preceding-bar value require 21 actual bars.
        if not self.closes.IsReady:
            return

        current_fast = sum(self.closes[i] for i in range(5)) / 5.0
        current_slow = sum(self.closes[i] for i in range(20)) / 20.0
        previous_fast = sum(self.closes[i] for i in range(1, 6)) / 5.0
        previous_slow = sum(self.closes[i] for i in range(1, 21)) / 20.0

        if previous_fast <= previous_slow and current_fast > current_slow:
            end_time = bar.EndTime
            if ((end_time.Hour > 9 or (end_time.Hour == 9 and end_time.Minute >= 45))
                    and (end_time.Hour < 14 or (end_time.Hour == 14 and end_time.Minute <= 30))):
                self.pending_entry_bar_end = end_time

    def OnData(self, data):
        self.HandleUnexpectedSpyPosition()
        self.HandleExpirationProtection()
        self.HandleOptionExit(data)
        self.HandlePendingEntry(data)

    def HandlePendingEntry(self, data):
        if self.pending_entry_bar_end is None:
            return

        # A crossover is considered only in the Slice immediately following its bar.
        pending_time = self.pending_entry_bar_end
        self.pending_entry_bar_end = None

        if pending_time != self.Time:
            return

        if self.no_entry_date == self.Time.date():
            return

        if self.held_option is not None or self.entry_ticket is not None:
            return

        if self.spy_flatten_ticket is not None or self.Portfolio[self.spy].Invested:
            return

        chain = data.OptionChains.get(self.option_symbol)
        if chain is None:
            self.Debug(f"{self.Time}: skipped entry; no option chain.")
            return

        current_spy_price = self.Securities[self.spy].Price
        if current_spy_price <= 0:
            self.Debug(f"{self.Time}: skipped entry; invalid SPY price.")
            return

        valid_expirations = sorted({
            self.AsDate(contract.Expiry)
            for contract in chain
            if (self.AsDate(contract.Expiry) - self.Time.date()).days >= 7
        })

        if not valid_expirations:
            self.Debug(f"{self.Time}: skipped entry; no expiration at least 7 calendar days away.")
            return

        selected_expiry = valid_expirations[0]
        minimum_strike = current_spy_price * 1.01

        candidates = [
            contract for contract in chain
            if contract.Right == OptionRight.Call
            and self.AsDate(contract.Expiry) == selected_expiry
            and float(contract.Strike) >= minimum_strike
        ]

        if not candidates:
            self.Debug(f"{self.Time}: skipped entry; no qualifying call at selected expiration.")
            return

        selected = sorted(candidates, key=lambda c: (float(c.Strike), str(c.Symbol)))[0]
        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug(
            f"{self.Time}: submitted call entry {selected.Symbol}, "
            f"expiry {selected_expiry}, strike {selected.Strike}."
        )

    def HandleOptionExit(self, data):
        if self.held_option is None or not self.Portfolio[self.held_option].Invested:
            return

        expiry = self.AsDate(self.held_option.ID.Date)

        # Never intentionally carry an option into its expiration date.
        if self.Time.date() >= expiry:
            self.no_entry_date = self.Time.date()
            self.SubmitExit("expiration protection")
            return

        if self.Time.date() == self.PreviousTradingDay(expiry):
            if self.Time.Hour == 15 and self.Time.Minute == 45:
                self.SubmitExit("day-before-expiration time stop")
                return

        if self.entry_price is None or self.entry_price <= 0:
            return

        quote = data.QuoteBars.get(self.held_option)
        if quote is None or quote.Bid is None or quote.Ask is None:
            return

        bid = float(quote.Bid.Close)
        ask = float(quote.Ask.Close)
        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= self.entry_price * 1.50:
            self.SubmitExit("50% profit target")

    def SubmitExit(self, reason):
        if self.held_option is None:
            return

        if self.exit_ticket is not None:
            status = self.exit_ticket.Status
            if status not in (OrderStatus.Filled, OrderStatus.Canceled, OrderStatus.Invalid):
                return

        quantity = self.Portfolio[self.held_option].Quantity
        if quantity == 0:
            return

        if self.exit_ticket is not None:
            self.exit_ticket.Cancel("Replacing outstanding exit order")

        self.exit_ticket = self.MarketOrder(self.held_option, -quantity)
        self.Debug(f"{self.Time}: submitted option exit ({reason}) for {self.held_option}.")

    def HandleExpirationProtection(self):
        if self.held_option is None or not self.Portfolio[self.held_option].Invested:
            return

        expiry = self.AsDate(self.held_option.ID.Date)
        if self.Time.date() >= expiry:
            self.no_entry_date = self.Time.date()
            self.SubmitExit("expiration protection")

    def HandleUnexpectedSpyPosition(self):
        if not self.Portfolio[self.spy].Invested:
            return

        if self.spy_flatten_ticket is not None:
            status = self.spy_flatten_ticket.Status
            if status not in (OrderStatus.Filled, OrderStatus.Canceled, OrderStatus.Invalid):
                return

        quantity = self.Portfolio[self.spy].Quantity
        if quantity != 0:
            self.Debug(f"{self.Time}: unexpected SPY exercise/assignment position; liquidating.")
            self.spy_flatten_ticket = self.MarketOrder(self.spy, -quantity)

    def OnOrderEvent(self, order_event):
        if self.entry_ticket is not None and order_event.OrderId == self.entry_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.held_option = order_event.Symbol
                self.entry_price = float(order_event.FillPrice)
                self.entry_ticket = None
                self.Debug(
                    f"{self.Time}: entry filled {self.held_option} "
                    f"at {self.entry_price:.2f}."
                )
            elif order_event.Status in (OrderStatus.Canceled, OrderStatus.Invalid):
                self.entry_ticket = None
                self.Debug(f"{self.Time}: entry order did not fill.")

        if self.exit_ticket is not None and order_event.OrderId == self.exit_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(
                    f"{self.Time}: exit filled {order_event.Symbol} "
                    f"at {float(order_event.FillPrice):.2f}."
                )
                self.exit_ticket = None
                self.held_option = None
                self.entry_price = None
            elif order_event.Status in (OrderStatus.Canceled, OrderStatus.Invalid):
                self.exit_ticket = None

        if (self.spy_flatten_ticket is not None
                and order_event.OrderId == self.spy_flatten_ticket.OrderId
                and order_event.Status in (OrderStatus.Filled, OrderStatus.Canceled, OrderStatus.Invalid)):
            self.spy_flatten_ticket = None

    def PreviousTradingDay(self, expiry_date):
        candidate = expiry_date - timedelta(days=1)
        hours = self.Securities[self.spy].Exchange.Hours

        while not hours.IsDateOpen(datetime(candidate.year, candidate.month, candidate.day), False):
            candidate -= timedelta(days=1)

        return candidate

    @staticmethod
    def AsDate(value):
        if hasattr(value, "date"):
            return value.date()
        return datetime(value.Year, value.Month, value.Day).date()
